def write(url, text):
 p=DIST / url.strip('/') / 'index.html';p.parent.mkdir(parents=True,exist_ok=True);p.write_text(text)
def arrow(): return '<span aria-hidden="true" class="arrow">↗</span>'
def header(): return f'''<a class="skip" href="#main">Skip to content</a><header class="site-header"><a class="logo-brand" href="/" aria-label="Episode Journal home"><img src="/assets/episode-journal-logo.png" alt="Episode Journal" width="2172" height="724"></a><nav aria-label="Main navigation"><a href="{SEASON}#episodes">Episodes</a><a href="{SEASON}#schedule">Subtitle updates</a><a href="{SEASON}#questions">Your questions</a></nav><a class="header-alert" href="{SEASON}#alerts">Get updates {arrow()}</a><button class="menu-button" aria-label="Open navigation" aria-expanded="false"><span></span><span></span></button></header>'''
def footer():return f'''<footer class="footer"><a class="logo-brand" href="/" aria-label="Episode Journal home"><img src="/assets/episode-journal-logo.png" alt="Episode Journal" width="2172" height="724" loading="lazy"></a><p>A clear guide to the next episode.<br>Broadcast dates. Subtitle updates. Viewing options.</p><div><a href="/how-we-check/">How we check</a><a href="/about/">About this guide</a><a href="{NUMBER_GUIDE}">Episode numbers</a><a href="{TRT}" target="_blank" rel="noopener">Official series {arrow()}</a></div><small>Independent guide · Design preview<br>Series photography © TRT / respective rights holders.</small></footer>'''
def shell(title,description,url,content,schema=None):return head(title,description,url,schema)+header()+'<main id="main">'+content+'</main>'+footer()+'</body></html>'

